-- P3: person templates for the whole system (outside projects). The owner
-- wants every permission screen to work person-first: pick a person, the
-- template suggested by their position fills the table, the Admin adds or
-- removes single permissions, then saves. A template is only a starting point
-- copied into the person's own grants; saving still goes through
-- public.update_user_authorization_v2 (catalog, scope, expiry and self-grant
-- checks, reason, audit). Editing a template later changes nobody.
-- Items: [{ permissionCode, scopeType (global|own|assigned), expiresInDays? }]
-- Only directly grantable codes; project codes live in Room templates and the
-- sensitive HR codes stay with the HR / HR_MANAGE roles.

create table if not exists public.user_permission_templates (
  code text primary key check (code ~ '^[a-z][a-z0-9_]{1,40}$'),
  name text not null check (length(btrim(name)) between 2 and 80),
  description text,
  items jsonb not null default '[]'::jsonb check (jsonb_typeof(items) = 'array'),
  -- hrm_positions ids for which this template is suggested
  suggested_position_ids uuid[] not null default '{}',
  sort_order integer not null default 100,
  is_active boolean not null default true,
  updated_by uuid references public.users(id),
  updated_at timestamptz not null default now()
);
alter table public.user_permission_templates enable row level security;
revoke all on public.user_permission_templates from anon, authenticated;
grant select on public.user_permission_templates to authenticated;
drop policy if exists user_permission_templates_select on public.user_permission_templates;
create policy user_permission_templates_select on public.user_permission_templates
  for select to authenticated using (true);

-- Keep only valid, directly grantable items; codes that need an end date get
-- expiresInDays (default 365, at most 730) so filling the form sets it.
create or replace function app_private.normalize_user_permission_template_items(p_items jsonb)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_item record;
  v_action public.permission_actions%rowtype;
  v_result jsonb := '[]'::jsonb;
  v_seen text[] := '{}';
  v_days integer;
begin
  if jsonb_typeof(coalesce(p_items, '[]'::jsonb)) <> 'array' then
    raise exception 'PERMISSION_TEMPLATE_INVALID' using errcode = '22023';
  end if;
  for v_item in
    select x."permissionCode" code, coalesce(nullif(x."scopeType", ''), 'global') scope, x."expiresInDays" days
    from jsonb_to_recordset(coalesce(p_items, '[]'::jsonb)) x("permissionCode" text, "scopeType" text, "expiresInDays" integer)
  loop
    select a.* into v_action from public.permission_actions a
    where a.permission_code = v_item.code and a.is_active;
    if v_action.id is null then
      raise exception 'PERMISSION_TEMPLATE_UNKNOWN: %', v_item.code using errcode = '22023';
    end if;
    if not v_action.direct_grant_allowed or v_item.code = 'system.settings.manage' then
      raise exception 'PERMISSION_TEMPLATE_NOT_DIRECT: %', v_item.code using errcode = '22023';
    end if;
    if v_item.scope <> all(array['global', 'own', 'assigned']) or v_item.scope <> all(v_action.scope_modes) then
      raise exception 'PERMISSION_TEMPLATE_SCOPE: %@%', v_item.code, v_item.scope using errcode = '22023';
    end if;
    continue when (v_item.code || '@' || v_item.scope) = any(v_seen);
    v_seen := v_seen || (v_item.code || '@' || v_item.scope);
    v_days := case when v_action.direct_grant_requires_expiry
      then least(greatest(coalesce(v_item.days, 365), 1), 730) end;
    v_result := v_result || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'permissionCode', v_item.code, 'scopeType', v_item.scope, 'expiresInDays', v_days)));
  end loop;
  return coalesce((
    select jsonb_agg(e order by e->>'permissionCode', e->>'scopeType')
    from jsonb_array_elements(v_result) e), '[]'::jsonb);
end;
$$;
revoke all on function app_private.normalize_user_permission_template_items(jsonb) from public, anon, authenticated;

create or replace function public.save_user_permission_template(
  p_code text, p_name text, p_description text, p_items jsonb,
  p_suggested_position_ids uuid[], p_is_active boolean
)
returns public.user_permission_templates
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row public.user_permission_templates;
  v_before jsonb;
begin
  if not public.is_admin() then
    raise exception 'PERMISSION_TEMPLATE_ADMIN_REQUIRED' using errcode = '42501';
  end if;
  select to_jsonb(t) into v_before from public.user_permission_templates t where t.code = p_code;
  insert into public.user_permission_templates (code, name, description, items, suggested_position_ids, is_active, updated_by, updated_at)
  values (p_code, btrim(p_name), nullif(btrim(coalesce(p_description, '')), ''),
          app_private.normalize_user_permission_template_items(p_items),
          coalesce(p_suggested_position_ids, '{}'), coalesce(p_is_active, true), public.current_app_user_id(), now())
  on conflict (code) do update set
    name = excluded.name, description = excluded.description, items = excluded.items,
    suggested_position_ids = excluded.suggested_position_ids, is_active = excluded.is_active,
    updated_by = excluded.updated_by, updated_at = now()
  returning * into v_row;
  insert into public.audit_trail (table_name, record_id, action, old_data, new_data, module, description)
  values ('user_permission_templates', v_row.code, case when v_before is null then 'INSERT' else 'UPDATE' end,
          v_before, to_jsonb(v_row), 'SETTINGS', 'Cập nhật mẫu quyền theo vị trí: ' || v_row.name);
  return v_row;
end;
$$;
revoke all on function public.save_user_permission_template(text, text, text, jsonb, uuid[], boolean) from public, anon;
grant execute on function public.save_user_permission_template(text, text, text, jsonb, uuid[], boolean) to authenticated;

